def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to ``maxsize`` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    import functools
    if maxsize < 0:
        raise ValueError("maxsize must be >= 0")
    if maxsize == 0:
        # trivial case: never cache
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kw):
                return func(*args, **kw)
            return wrapper
        return decorator

    def decorator(func):
        cache = {}
        # mapping: key -> (value, freq)
        freqs = {}
        hits, misses = 0, 0

        def make_key(args, kw, typed):
            """Create a hashable key from function arguments."""
            key = args
            if kw:
                # use a frozenset of items to keep order-independent
                key += (object(),)  # separator so tuple sizes don't clash
                for k in sorted(kw):
                    key += (k, kw[k])
            if typed:
                key = tuple((arg, type(arg)) for arg in key)
            return key

        @functools.wraps(func)
        def wrapper(*args, **kw):
            nonlocal hits, misses
            key = make_key(args, kw, typed)
            if key in cache:
                # Increment frequency
                freq = freqs[key] + 1
                freqs[key] = freq
                hits += 1
                return cache[key]
            # miss
            misses += 1
            result = func(*args, **kw)
            if len(cache) >= maxsize:
                # evict one with lowest freq; ties broken arbitrarily
                # find the key with minimum freq
                min_freq = min(freqs.values())
                for evict_key, f in freqs.items():
                    if f == min_freq:
                        break
                # remove
                cache.pop(evict_key, None)
                freqs.pop(evict_key, None)
            cache[key] = result
            freqs[key] = 1
            return result

        wrapper.cache_info = lambda: (hits, misses, len(cache), maxsize)
        return wrapper

    return decorator

