def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the coordinate is a sequence of the right dimensionality
    try:
        coords = list(coord)
    except TypeError:
        coords = [coord]

    if len(coords) != len(self.edges):
        raise ValueError("Coordinate dimensionality must match histogram edges")

    # Determine whether each coordinate lies inside the valid area
    idx = []
    for dim, c in enumerate(coords):
        # If the coordinate is outside the edge range, ignore it
        if c < self.edges[dim][0] or c >= self.edges[dim][-1]:
            return  # outside → ignore
        # Find the bin index for this axis using binary search
        lo, hi = 0, len(self.edges[dim]) - 1
        while lo < hi - 1:
            mid = (lo + hi) // 2
            if c < self.edges[dim][mid]:
                hi = mid
            else:
                lo = mid
        idx.append(lo)

