def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters:
        pieces (iterable): Elements representing parts of the version. Each element
                           should support a ``render`` method, a ``to_dict`` method,
                           a ``to_xml`` method, or simply be convertible to a string.
        style (str): The style to render into. Supported values are ``plain``,
                     ``html``, ``json``, and ``xml``.

    Returns:
        str: The rendered representation of the pieces.

    Raises:
        ValueError: If an unsupported style is supplied.
    """
    style = style.lower()
    if style == 'plain':
        return ''.join(str(p) for p in pieces)
    if style == 'html':
        return ''.join(
            p.render('html') if hasattr(p, 'render') else str(p)
            for p in pieces
        )
    if style == 'json':
        import json
        data = [
            p.to_dict() if hasattr(p, 'to_dict') else str(p)
            for p in pieces
        ]
        return json.dumps(data)
    if style == 'xml':
        parts = []
        for p in pieces:
            if hasattr(p, 'to_xml'):
                parts.append(p.to_xml())
            else:
                parts.append(f"<piece>{str(p)}</piece>")
        return '<root>' + ''.join(parts) + '</root>'
    raise ValueError(f"Unsupported style: {style}")

