import configparser, json, os

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    result = {}
    errors = []
    logger = logging.getLogger(__name__)
    for fn in config_filenames:
        try:
            if fn.lower().endswith('.json'):
                with open(fn, 'r', encoding='utf-8') as f:
                    cfg = json.load(f)
            elif fn.lower().endswith(('.ini', '.cfg', '.cnf')):
                parser = configparser.ConfigParser()
                with open(fn, 'r', encoding='utf-8') as f:
                    parser.read_file(f)
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                # fallback: try configparser
                parser = configparser.ConfigParser()
                with open(fn, 'r', encoding='utf-8') as f:
                    parser.read_file(f)
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
        except Exception as e:
            # create LogRecord
            record = logger.makeRecord(
                name='load_configurations',
                level=logging.ERROR,
                fn=fn,
                lno=0,
                msg='Error parsing configuration file {}: {}'.format(fn, e),
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        if overrides:
            # apply overrides at top-level keys
            if isinstance(overrides, dict):
                cfg.update({k: v for k, v in overrides.items() if k in cfg})
            else:
                # non-dict overrides not supported
                record = logger.makeRecord(
                    name='load_configurations',
                    level=logging.WARNING,
                    fn=fn,
                    lno=0,
                    msg='Overrides provided but not a dict; ignored.',
                    args=(),
                    exc_info=None
                )
                errors.append(record)

        if resolve_env:
            def resolve(d):
                if isinstance(d, dict):
                    return {k: resolve(v) for k, v in d.items()}
                elif isinstance(d, list):
                    return [resolve(v) for v in d]
                elif isinstance(d, str):
                    # replace ${VAR} or $VAR
                    try:
                        return os.path.expandvars(d)
                    except Exception:
                        return d
                else:
                    return d
            cfg = resolve(cfg)

        result[fn] = cfg

    return result, errors
